import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";import"./chunks/assets.B8sWdo1g.js";var i=JSON.parse(`{"title":"系統架構設計","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 三處理程序隔離模型","slug":"_1-三處理程序隔離模型","link":"#_1-三處理程序隔離模型","children":[{"level":3,"title":"1. 背景索引服務（Lertaro.Service.exe）","slug":"_1-背景索引服務-lertaro-service-exe","link":"#_1-背景索引服務-lertaro-service-exe","children":[]},{"level":3,"title":"2. 使用者互動主程式（Lertaro.App）","slug":"_2-使用者互動主程式-lertaro-app","link":"#_2-使用者互動主程式-lertaro-app","children":[]},{"level":3,"title":"3. 全域鍵盤攔截與視窗適配處理程序（Lertaro.Service --hook）","slug":"_3-全域鍵盤攔截與視窗適配處理程序-lertaro-service-hook","link":"#_3-全域鍵盤攔截與視窗適配處理程序-lertaro-service-hook","children":[]}]},{"level":2,"title":"2. 共用核心層（Shared Core Library）","slug":"_2-共用核心層-shared-core-library","link":"#_2-共用核心層-shared-core-library","children":[]},{"level":2,"title":"3. 外掛模組系統在架構中的定位","slug":"_3-外掛模組系統在架構中的定位","link":"#_3-外掛模組系統在架構中的定位","children":[]}],"relativePath":"zh-TW/dev-guide/architecture.md","filePath":"zh-TW/dev-guide/architecture.md","lastUpdated":1791112464000}`),a={name:`zh-TW/dev-guide/architecture.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="系統架構設計" tabindex="-1">系統架構設計 <a class="header-anchor" href="#系統架構設計" aria-label="Permalink to “系統架構設計”">​</a></h1><p>Lertaro 採用多處理程序隔離與模組化分層設計，確保在實現毫秒級檢索與視窗整合的同時，兼顧執行安全與穩定性。</p><p><img src="/architecture-zh-CN.svg" alt="Lertaro 架構圖" width="840" height="310"></p><h2 id="_1-三處理程序隔離模型" tabindex="-1">1. 三處理程序隔離模型 <a class="header-anchor" href="#_1-三處理程序隔離模型" aria-label="Permalink to “1. 三處理程序隔離模型”">​</a></h2><p>為了規避單一元件異常導致整個系統當機，並將 Windows 特權限制在最小範圍內，Lertaro 的執行階段被明確劃分為三個獨立的處理程序：</p><h3 id="_1-背景索引服務-lertaro-service-exe" tabindex="-1">1. 背景索引服務（<code>Lertaro.Service.exe</code>） <a class="header-anchor" href="#_1-背景索引服務-lertaro-service-exe" aria-label="Permalink to “1. 背景索引服務（Lertaro.Service.exe）”">​</a></h3><ul><li><strong>執行身分</strong>：以 Windows 系統級 <code>LocalSystem</code> 身分常駐執行的 Windows 服務。</li><li><strong>職責範圍</strong>：負責全盤檔案索引與增量監聽。直接讀取 NTFS / ReFS 磁碟底層的 USN 變更記錄檔與 $MFT 主檔案表；即時監聽 FAT32 / exFAT 磁碟變更；定時抓取並快取 SMB / NAS 網路共用。</li><li><strong>安全與效能考量</strong>：執行在 SYSTEM 級別使服務無需快顯任何 UAC 提權快顯視窗即可直接讀取原始磁碟卷的中繼資料；同時透過高效能具名管道向使用者態 App 返回檢索結果，避免前景 UI 處理程序持有不必要的全域高權限。</li></ul><h3 id="_2-使用者互動主程式-lertaro-app" tabindex="-1">2. 使用者互動主程式（<code>Lertaro.App</code>） <a class="header-anchor" href="#_2-使用者互動主程式-lertaro-app" aria-label="Permalink to “2. 使用者互動主程式（Lertaro.App）”">​</a></h3><ul><li><strong>執行身分</strong>：標準 Windows 使用者態、Session 隔離的 WPF 前景桌面應用程式。</li><li><strong>職責範圍</strong>：承載快速搜尋置中浮動視窗、完整主搜尋視窗、設定中心、全域快速鍵分發、動作功能表（<code>Ctrl+O</code>）以及 QuickLook 檔案即時預覽介面。</li><li><strong>IPC 橋樑與 CLI 裝載</strong>：透過雙向具名管道 <code>LertaroPipe</code> 與背景 Service 溝通（<code>Core.Services.Search.SearchService</code> 是 App 側的客戶端）；同時，App 自身還裝載了一條面向目前使用者的專屬具名管道服務（<code>AppSearchPipeService</code>），使外部伴隨工具（如 <code>lff</code> 命令列工具）能直接複用 App 已經建置好的記憶體別名表、外掛模組提供者與網路磁碟快取，無需重複初始化。</li></ul><h3 id="_3-全域鍵盤攔截與視窗適配處理程序-lertaro-service-hook" tabindex="-1">3. 全域鍵盤攔截與視窗適配處理程序（<code>Lertaro.Service --hook</code>） <a class="header-anchor" href="#_3-全域鍵盤攔截與視窗適配處理程序-lertaro-service-hook" aria-label="Permalink to “3. 全域鍵盤攔截與視窗適配處理程序（Lertaro.Service --hook）”">​</a></h3><ul><li><strong>執行身分</strong>：由背景服務拉起的獨立輔助處理程序。只有當登入帳號是真正的管理員時，它才會<strong>以提權方式啟動</strong>；否則它沿用使用者自己的權杖，因此下述的權限突破只在這類機器上可用。</li><li><strong>職責範圍</strong>：裝載低階全域鍵盤攔截（Low-Level Keyboard Hook）與滑鼠全域監聽。</li><li><strong>UIPI 權限突破與當機隔離</strong>：在 Windows 安全體系中，低完整性級別的使用者態處理程序無法向以管理員身分執行的最高權限視窗發送視窗訊息或模擬輸入（UIPI 隔離）。透過在該 Hook 處理程序中執行視窗整合適配器（<a href="./sdk/system-adapters.html"><code>IActivePathCollector</code>、<code>IFileDialogAdapter</code>、<code>IInlineSearchAdapter</code></a>），只要 Hook 是以提權方式啟動的，Lertaro 就能讀取並驅動由管理員身分啟動的檔案總管、Total Commander 或第三方對話方塊。同時，即使底層攔截因第三方遊戲的反作弊模組產生異常，也不會影響主 App 處理程序的正常執行。</li></ul><h2 id="_2-共用核心層-shared-core-library" tabindex="-1">2. 共用核心層（Shared Core Library） <a class="header-anchor" href="#_2-共用核心層-shared-core-library" aria-label="Permalink to “2. 共用核心層（Shared Core Library）”">​</a></h2><p><code>Lertaro.Core</code> 是被 Service、App 和 Hook 處理程序同時引用的基礎類別庫，主要包含以下關鍵模組：</p><ul><li><strong>自研 fzf 模糊比對引擎（<code>Core/SearchIndex/Fzf/*</code>）</strong>：復刻並最佳化了知名 <code>fzf</code> 演算法的跳躍字元模糊比對、子字串分段與字元級反白計算，配合 <code>SearchQueryParser</code> 實現磁碟機定向與路徑模式切分。</li><li><strong>欄式記憶體索引（<code>Core/IndexV2/*</code>）</strong>：採用記憶體對應欄式快照（Columnar Snapshot）與記憶體增量覆蓋層（Delta Overlay），實現億級檔案項目的亞毫秒級檢索。</li><li><strong>二進位 IPC 通訊契約</strong>：定義了 <code>SearchRequestMessage</code>、<code>SearchResponseBinarySerializer</code> 等標準二進位資料通訊協定，確保多處理程序間零拷貝高效序列化。</li><li><strong>統一多處理程序記錄系統（<code>Logger</code>）</strong>：分別輸出至 <code>service.log</code>、<code>app.log</code> 與 <code>hook.log</code>，並由 App 的設定中心記錄檢視器統一代理讀取與呈現。</li></ul><h2 id="_3-外掛模組系統在架構中的定位" tabindex="-1">3. 外掛模組系統在架構中的定位 <a class="header-anchor" href="#_3-外掛模組系統在架構中的定位" aria-label="Permalink to “3. 外掛模組系統在架構中的定位”">​</a></h2><p>所有第三方及內建外掛模組均基於 <code>Lertaro.PluginSdk</code> 建置，由 <code>Lertaro.App</code> 處理程序在啟動時自動反映掃描並載入：</p><ul><li><strong>零特權直接通訊</strong>：外掛模組自身的程式碼與載入它的處理程序在同程序內執行——通常是 App，但 Service 也會載入的兩種類別請看下一項。程式碼本身不會自行跨越處理程序邊界，因此需要註冊自訂目錄索引的外掛模組會透過 <code>DirectoryIndexerService</code> 委派這項工作，而不是自己去周遊磁碟。</li><li><strong>選擇性雙重載入機制</strong>：搜尋來源、動作與介面擴充元件僅在 App 處理程序中執行。有三類元件會被額外載入到其他處理程序：視窗與檔案對話方塊適配器（<code>IActivePathCollector</code>、<code>IFileDialogAdapter</code>、<code>IInlineSearchAdapter</code>）會進入 Hook 處理程序，以處理跨權限的視窗自動化；而 <code>IAliasProvider</code> 與 <code>ITranslationProvider</code> 也會由 <strong>Service</strong> 載入（<code>ServicePluginLoader</code>），因為索引器要建置別名資料列，需要與介面顯示相同的轉寫與命名。</li></ul>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};